const msg = $json.message ?? {};
const photos = Array.isArray(msg.photo) ? msg.photo : [];
const bestPhoto = photos.length ? photos[photos.length - 1] : null;

return [{
  updateId: $json.update_id ?? null,
  chatId: msg.chat?.id ?? null,
  userId: msg.from?.id ?? null,
  username: msg.from?.username ?? '',
  fullName: [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' ').trim(),
  text: String(msg.text ?? '').trim(),
  caption: String(msg.caption ?? '').trim(),
  fileId: bestPhoto?.file_id ?? '',
  hasPhoto: Boolean(bestPhoto?.file_id),
  sentAt: msg.date ? new Date(msg.date * 1000).toISOString() : new Date().toISOString()
}];

const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};

const userKey = String($json.userId || $json.chatId || 'unknown');
let session = store.sessions[userKey] || {
  step: 'idle',
  answers: {},
  updatedAt: new Date().toISOString()
};

const now = Date.now();
const updatedAtTs = Date.parse(session.updatedAt || 0);
const oneDayMs = 24 * 60 * 60 * 1000;
if (updatedAtTs && now - updatedAtTs > oneDayMs) {
  session = {
    step: 'idle',
    answers: {},
    updatedAt: new Date().toISOString()
  };
}

const text = String($json.text || '').trim();
const lower = text.toLowerCase();

const saveSession = () => {
  session.updatedAt = new Date().toISOString();
  store.sessions[userKey] = session;
};

const resetSession = () => {
  session = {
    step: 'awaiting_height',
    answers: {},
    updatedAt: new Date().toISOString()
  };
  saveSession();
};

const reply = (replyText) => [{
  ...$json,
  action: 'reply_only',
  replyText,
  questionnaire: session.answers
}];

const parseNumber = (value) => {
  if (!value) return null;
  const match = String(value).replace(',', '.').match(/\d+(?:\.\d+)?/);
  return match ? Number(match[0]) : null;
};

const startCommands = ['/start', '/anketa', '/questionnaire', '/reset'];
if (startCommands.includes(lower)) {
  resetSession();
  return reply(
    '<b>Анкета начата</b>\n\n' +
    'Шаг 1/5. Напиши свой <b>рост в см</b>.\n' +
    'Пример: <code>178</code>'
  );
}

if (lower === '/status') {
  const answers = session.answers || {};
  return reply(
    '<b>Текущий статус анкеты</b>\n\n' +
    `Шаг: <code>${session.step}</code>\n` +
    `Рост: <code>${answers.heightCm ?? '-'}</code>\n` +
    `Вес: <code>${answers.weightKg ?? '-'}</code>\n` +
    `Цель: <code>${answers.goal ?? '-'}</code>\n` +
    `Опыт: <code>${answers.experience ?? '-'}</code>\n` +
    `Травмы: <code>${answers.injuries ?? '-'}</code>\n\n` +
    'Для перезапуска отправь <code>/reset</code>.'
  );
}

if (session.step === 'idle') {
  return reply(
    '<b>Привет</b>\n\n' +
    'Я сначала собираю анкету, потом прошу фото и строю программу тренировок.\n\n' +
    'Отправь <code>/start</code>, чтобы начать.\n' +
    'Команды: <code>/status</code>, <code>/reset</code>.'
  );
}

if (session.step === 'awaiting_height') {
  const heightCm = parseNumber(text);
  if (!heightCm || heightCm < 120 || heightCm > 230) {
    return reply('Не понял рост. Напиши число в сантиметрах, например <code>178</code>.');
  }

  session.answers.heightCm = heightCm;
  session.step = 'awaiting_weight';
  saveSession();
  return reply(
    '<b>Шаг 2/5</b>\n\n' +
    `Рост сохранен: <code>${heightCm} см</code>\n` +
    'Теперь напиши <b>вес в кг</b>.\n' +
    'Пример: <code>82</code>'
  );
}

if (session.step === 'awaiting_weight') {
  const weightKg = parseNumber(text);
  if (!weightKg || weightKg < 35 || weightKg > 300) {
    return reply('Не понял вес. Напиши число в килограммах, например <code>82</code>.');
  }

  session.answers.weightKg = weightKg;
  session.step = 'awaiting_goal';
  saveSession();
  return reply(
    '<b>Шаг 3/5</b>\n\n' +
    `Вес сохранен: <code>${weightKg} кг</code>\n` +
    'Какая у тебя цель?\n' +
    'Пример: <code>похудение</code>, <code>набор массы</code>, <code>рекомпозиция</code>.'
  );
}

if (session.step === 'awaiting_goal') {
  if (!text || text.length < 3) {
    return reply('Опиши цель чуть подробнее. Например: <code>похудение</code> или <code>набор массы</code>.');
  }

  session.answers.goal = text;
  session.step = 'awaiting_experience';
  saveSession();
  return reply(
    '<b>Шаг 4/5</b>\n\n' +
    `Цель сохранена: <code>${text}</code>\n` +
    'Какой у тебя опыт тренировок?\n' +
    'Пример: <code>новичок</code>, <code>занимался 1 год</code>, <code>опытный</code>.'
  );
}

if (session.step === 'awaiting_experience') {
  if (!text || text.length < 3) {
    return reply('Напиши опыт тренировок текстом. Например: <code>новичок</code>.');
  }

  session.answers.experience = text;
  session.step = 'awaiting_injuries';
  saveSession();
  return reply(
    '<b>Шаг 5/5</b>\n\n' +
    `Опыт сохранен: <code>${text}</code>\n` +
    'Есть ли травмы, боли или ограничения?\n' +
    'Если нет, напиши <code>нет</code>.'
  );
}

if (session.step === 'awaiting_injuries') {
  if (!text) {
    return reply('Напиши ограничения текстом. Если ограничений нет, отправь <code>нет</code>.');
  }

  session.answers.injuries = text;
  session.step = 'awaiting_photo';
  saveSession();
  return reply(
    '<b>Анкета заполнена</b>\n\n' +
    `Рост: <code>${session.answers.heightCm} см</code>\n` +
    `Вес: <code>${session.answers.weightKg} кг</code>\n` +
    `Цель: <code>${session.answers.goal}</code>\n` +
    `Опыт: <code>${session.answers.experience}</code>\n` +
    `Травмы/ограничения: <code>${session.answers.injuries}</code>\n\n` +
    'Теперь пришли <b>одно фото</b> в полный рост или по пояс.\n' +
    'Можно добавить подпись: <code>дома, 3 тренировки в неделю</code>.'
  );
}

if (session.step === 'awaiting_photo') {
  if (!$json.hasPhoto) {
    return reply('Жду фото. Пришли одно фото в полный рост или по пояс. Для перезапуска анкеты отправь <code>/reset</code>.');
  }

  session.answers.photoComment = $json.caption || '';
  session.step = 'analyzing';
  saveSession();

  return [{
    ...$json,
    action: 'analyze',
    replyText: '',
    questionnaire: session.answers
  }];
}

if (session.step === 'analyzing') {
  return reply('Сейчас уже обрабатываю предыдущее фото. Если нужно начать заново, отправь <code>/reset</code>.');
}

return reply('Не удалось определить шаг анкеты. Отправь <code>/reset</code> и начни заново.');

const binary = $input.item.binary?.data;
if (!binary?.data) {
  throw new Error('Не удалось получить бинарные данные фото из Telegram.');
}

const meta = $('Questionnaire Router').first().json;
const q = meta.questionnaire || {};
const mimeType = binary.mimeType || 'image/jpeg';
const fileSize = Number(binary.fileSize || 0);
const maxSize = 15 * 1024 * 1024;

if (fileSize && fileSize > maxSize) {
  return [{
    ...meta,
    action: 'reply_only',
    replyText: 'Фото слишком большое. Пришли изображение до 15 МБ.',
    questionnaire: q
  }];
}

if (!mimeType.startsWith('image/')) {
  return [{
    ...meta,
    action: 'reply_only',
    replyText: 'Нужна именно фотография. Пришли изображение в формате JPG или PNG.',
    questionnaire: q
  }];
}

return [{
  ...meta,
  questionnaire: q,
  action: 'analyze_ready',
  mimeType,
  dataUrl: `data:${mimeType};base64,${binary.data}`
}];

