parameters.jsCode:
const meta = $('Build Vision Payload').first().json;

const fallbackReply = (text) => [{
  chatId: meta.chatId,
  userId: meta.userId,
  reply: text
}];

// OpenRouter Chat Completions format: choices[0].message.content
const rawText = $json.choices?.[0]?.message?.content || '';

if (!rawText) {
  return fallbackReply('Сервис анализа временно не смог обработать фото. Попробуй еще раз через пару минут или отправь /reset.');
}

let parsed;
try {
  parsed = typeof rawText === 'string' ? JSON.parse(rawText) : rawText;
} catch (error) {
  return fallbackReply('Сервис анализа вернул некорректный ответ. Попробуй повторить позже.');
}

const requiredFields = ['bodyType', 'confidence', 'rationale', 'limitations', 'strategy', 'schedule', 'progression', 'nutrition', 'safety', 'followUpQuestions'];
const missing = requiredFields.filter((field) => parsed[field] === undefined || parsed[field] === null);
if (missing.length) {
  return fallbackReply(`Модель вернула неполный ответ. Не хватает полей: ${missing.join(', ')}.`);
}

const q = meta.questionnaire || {};
const esc = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const bodyTypeMap = {
  ectomorph: 'Эктоморф',
  mesomorph: 'Мезоморф',
  endomorph: 'Эндоморф',
  mixed: 'Смешанный тип',
  unclear: 'Неопределенно'
};

const listBlock = (items) => (items || []).map((item) => `• ${esc(item)}`).join('\n');

const schedule = (parsed.schedule || []).map((day) => {
  const exercises = (day.exercises || []).map((exercise) => `• ${esc(exercise)}`).join('\n');
  const alternatives = (day.alternativesForInjuries || []).map((item) => `• ${esc(item)}`).join('\n');

  return `<b>${esc(day.day)}:</b> ${esc(day.focus)}\n` +
    `Разминка: ${esc(day.warmup)}\n` +
    `${exercises}\n` +
    `Кардио: ${esc(day.cardio)}\n` +
    `Альтернативы с учетом ограничений:\n${alternatives}\n` +
    `Комментарий: ${esc(day.notes)}`;
}).join('\n\n');

const reply = [
  '<b>Анкета</b>',
  `Рост: <code>${esc(q.heightCm)} см</code>`,
  `Вес: <code>${esc(q.weightKg)} кг</code>`,
  `Цель: <code>${esc(q.goal)}</code>`,
  `Опыт: <code>${esc(q.experience)}</code>`,
  `Ограничения: <code>${esc(q.injuries)}</code>`,
  '',
  '<b>Оценка по фото</b>',
  `<b>Вероятный тип:</b> ${esc(bodyTypeMap[parsed.bodyType] || parsed.bodyType)}`,
  `<b>Уверенность:</b> ${esc(parsed.confidence)}%`,
  '',
  '<b>Почему такой вывод</b>',
  listBlock(parsed.rationale),
  '',
  '<b>Ограничения оценки</b>',
  listBlock(parsed.limitations),
  '',
  '<b>Стратегия тренировок</b>',
  listBlock(parsed.strategy),
  '',
  '<b>Программа на 4 недели</b>',
  schedule,
  '',
  '<b>Как повышать нагрузку</b>',
  listBlock(parsed.progression),
  '',
  '<b>Питание и восстановление</b>',
  listBlock(parsed.nutrition),
  '',
  '<b>Безопасность</b>',
  listBlock(parsed.safety),
  '',
  '<b>Что еще уточнить</b>',
  listBlock(parsed.followUpQuestions),
  '',
  'Чтобы пройти анкету заново, отправь <code>/reset</code>.'
].join('\n');

return [{
  chatId: meta.chatId,
  userId: meta.userId,
  reply
}];

const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
const userKey = String($json.userId || $json.chatId || 'unknown');

store.sessions[userKey] = {
  step: 'idle',
  answers: {},
  updatedAt: new Date().toISOString(),
  lastCompletedAt: new Date().toISOString()
};

return [$input.item];
